// Builds index.html: wraps paint-booth.html (the page body, also used for the Claude artifact)
// into a standalone HTML document that opens directly in a browser.
// Usage: node build.js
const fs = require('fs');
const path = require('path');

const src = fs.readFileSync(path.join(__dirname, 'paint-booth.html'), 'utf8');
const split = src.indexOf('<div class="wrap">');
if (split < 0) throw new Error('Could not find <div class="wrap"> in paint-booth.html');

const head = src.slice(0, split).trim();
const body = src.slice(split).trim();

const html = `<!doctype html>
<!-- Generated by build.js from paint-booth.html. Edit paint-booth.html, then run: node build.js -->
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<style>:root{color-scheme:light}body{margin:0;font:14px system-ui,sans-serif}img{max-width:100%}[hidden]{display:none!important}</style>
${head}
</head>
<body>
${body}
</body>
</html>
`;

fs.writeFileSync(path.join(__dirname, 'index.html'), html);
console.log('Wrote index.html (' + Math.round(html.length / 1024) + ' KB)');
